// Title: Set default font to Courier New with HtmlSaveOptions and verify font fallback when exporting Excel to HTML using Aspose.Cells in C#
// Common Searches: Aspose.Cells C# export Excel to HTML with default font Courier New | how to verify missing font fallback in HTML output generated by Aspose.Cells | using HtmlSaveOptions to embed images as Base64 and set default font in C# | check if non‑existent font is replaced by fallback font in Aspose.Cells HTML export | C# code sample for HtmlSaveOptions default font configuration and fallback verification
// Tags: HtmlSaveOptions default font configuration | HTML export fallback font verification | Aspose.Cells embed images as Base64 | Excel to HTML conversion C# | nonexistent font handling Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;

namespace AsposeCellsHtmlDefaultFontDemo
{
    // The example creates a workbook, writes text to a cell, applies a style that references a font that does not exist, configures HtmlSaveOptions (including ExportImagesAsBase64), saves the workbook as an HTML file, reads the generated HTML, and checks whether the missing font name appears. Absence of the missing font confirms that the fallback to the default font (e.g., Courier New) succeeded.
    class Program
    {
        static void Main(string[] args)
        {
            // Path for the generated HTML file
            string htmlOutputPath = "output.html";

            try
            {
                // ------------------------------------------------------------
                // 1. Create a new workbook and add sample data
                // ------------------------------------------------------------
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];

                // Put some text into a cell
                Cell cell = sheet.Cells["A1"];
                cell.PutValue("This text uses a non‑existent font.");

                // Apply a style that references a font that does NOT exist on the system
                Style style = workbook.CreateStyle();
                style.Font.Name = "FakeFontThatDoesNotExist";
                cell.SetStyle(style);

                // ------------------------------------------------------------
                // 2. Configure HtmlSaveOptions
                // ------------------------------------------------------------
                HtmlSaveOptions htmlOptions = new HtmlSaveOptions
                {
                    // Export images as Base64 to keep everything in a single file
                    ExportImagesAsBase64 = true
                };

                // ------------------------------------------------------------
                // 3. Save the workbook as HTML using the configured options
                // ------------------------------------------------------------
                workbook.Save(htmlOutputPath, htmlOptions);
                Console.WriteLine($"Workbook saved to HTML file: {htmlOutputPath}");

                // ------------------------------------------------------------
                // 4. Verify that the fallback font appears in the generated HTML
                // ------------------------------------------------------------
                if (File.Exists(htmlOutputPath))
                {
                    string htmlContent = File.ReadAllText(htmlOutputPath);

                    bool containsMissingFont = htmlContent.IndexOf("FakeFontThatDoesNotExist", StringComparison.OrdinalIgnoreCase) >= 0;

                    Console.WriteLine();
                    Console.WriteLine("Verification Results:");
                    Console.WriteLine($"- Missing font \"FakeFontThatDoesNotExist\" still present: {(containsMissingFont ? "YES (fallback failed)" : "NO (fallback succeeded)")}");

                    // Simple assertion to make the demo explicit
                    if (!containsMissingFont)
                    {
                        Console.WriteLine("Fallback behavior verified successfully.");
                    }
                    else
                    {
                        Console.WriteLine("Fallback behavior verification failed. Check the generated HTML for font declarations.");
                    }
                }
                else
                {
                    Console.WriteLine($"Error: HTML file \"{htmlOutputPath}\" was not created.");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred during processing:");
                Console.WriteLine(ex.Message);
                Console.WriteLine(ex.StackTrace);
            }
        }
    }
}
